use verus::prelude::*;

verus! {
    /// Replaces all occurrences of `old_char` in `str1` with `new_char`,
    /// returning a fresh Vec<char> of the same length.
    ///
    /// Specification:
    ///   - The result has the same length as `str1`.
    ///   - For each index `i`,
    ///       if `str1[i] == old_char` then `result[i] == new_char`
    ///       else                    `result[i] == str1[i]`.
    fn replace_chars(str1: &Vec<char>, old_char: char, new_char: char) -> Vec<char>
        ensures |result: &Vec<char>|
            result.len() == str1.len() &&
            forall(|i: usize| i < str1.len() ==>
                (if str1[i] == old_char {
                    result[i] == new_char
                } else {
                    result[i] == str1[i]
                })
            )
    {
        // Build up the result in `res` one character at a time.
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // Loop over all indices of str1.
        while i < str1.len()
            invariant i <= str1.len();
            invariant res.len() == i;
            invariant forall(|j: usize| j < i ==>
                if str1[j] == old_char {
                    res[j] == new_char
                } else {
                    res[j] == str1[j]
                }
            );
            decreases str1.len() - i;
        {
            let c = str1[i];
            if c == old_char {
                res.push(new_char);
            } else {
                res.push(c);
            }
            i += 1;
        }

        // At this point i == str1.len() and res.len() == str1.len(),
        // and by the loop invariant every character is correctly replaced.
        res
    }
}